} from "lucide-react";
import { useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { api } from "../../lib/api";
import { formatDateTime } from "../../lib/utils";
import { appStatusLabel } from "../apps/app-status";
import {
  Button,
  Card,
  ErrorState,
  Field,
  Input,
  LoadingState,
  PageHeader,
} from "../../components/ui";
import type { SecurityCheckView } from "../../types";

// SecCheck's own wording for where a review stands, so an owner reading both
// screens sees the same words.
const REMOTE_STATUS: Record<string, string> = {
  UNVERIFIED: "미확인",
  DRAFT: "작성 중",
  CHANGE_REQUESTED: "보완 요청",
  SUBMITTED: "제출됨",
  RESUBMITTED: "재제출됨",
  REVIEWING: "검토 중",
  APPROVAL_PENDING: "승인 대기",
  APPROVED: "승인됨",
  REJECTED: "반려됨",
  CANCELLED: "취소됨",
  CLOSED: "종료됨",
};

export function AppSecurityCheckPage() {
  const { id = "" } = useParams();
  const navigate = useNavigate();
  const client = useQueryClient();
  const [reviewId, setReviewId] = useState("");
  const [copied, setCopied] = useState(false);
  const check = useQuery({
    queryKey: ["app-security-check", id],
    queryFn: ({ signal }) => api.appSecurityCheck(id, signal),
    enabled: !!id,
  });
  const verify = useMutation({
    mutationFn: (value: string) => api.verifyAppSecurityCheck(id, value),
    onSuccess: async (result) => {
      client.setQueryData(["app-security-check", id], result);
      await client.invalidateQueries({ queryKey: ["my-apps"] });
    },
  });
  const submit = useMutation({
    mutationFn: () => api.submitApp(id),
    onSuccess: async () => {
      await client.invalidateQueries({ queryKey: ["my-apps"] });
      await client.invalidateQueries({ queryKey: ["app-security-check", id] });
      navigate("/my/apps");
    },
  });

  if (check.isPending)
    return (
      <div className="page">
        <LoadingState label="보안 심의 상태를 불러오는 중입니다" />
      </div>
    );
  if (check.error)
    return (
      <div className="page">
        <ErrorState error={check.error} retry={() => void check.refetch()} />
      </div>
    );
  const view = check.data as SecurityCheckView;
  const waiting = view.status !== "UNVERIFIED" && !view.verified;

  return (
    <div className="page">
      <PageHeader
        eyebrow="Security review"
        title="보안 심의"
        description={`${view.appName} · SecCheck에서 이 앱의 보안 심의를 받고, 승인 결과를 여기에서 확인합니다.`}
        actions={
          <Link className="button button-secondary" to="/my/apps">
            <ArrowLeft size={17} /> 내 앱
          </Link>
        }
      />

      {!view.enabled && (
        <div className="notice mt-5">
          이 조직은 보안 심의를 필수로 적용하고 있지 않습니다. 심의를 마치면
                조건부 승인이나 종료된 심의로는 제출할 수 없습니다.
              </p>
            )}
          </Card>
        </div>

        <Card className="prose-card">
          <h2>심의 상태</h2>
          <div className="badge-row">
            {view.verified ? (
              <span className="badge badge-positive">
                <ShieldCheck size={14} aria-hidden="true" /> 보안 심의 완료
              </span>
            ) : (
              <span className="badge badge-warning">
                {waiting ? "심의 진행 중" : "미확인"}
              </span>
            )}
          </div>
          <dl className="meta-list mt-5">
            <div className="meta-row">
              <dt>SecCheck 상태</dt>
              <dd>{REMOTE_STATUS[view.status] ?? view.status}</dd>
            </div>
            <div className="meta-row">
              <dt>심의 번호</dt>
              <dd>{view.reviewNumber || "—"}</dd>
            </div>
            <div className="meta-row">
              <dt>최종 결과</dt>
              <dd>{view.finalResult || "—"}</dd>
            </div>
            <div className="meta-row">
              <dt>승인 시각</dt>
              <dd>{view.approvedAt ? formatDateTime(view.approvedAt) : "—"}</dd>
            </div>
            <div className="meta-row">
              <dt>마지막 확인</dt>
              <dd>{view.checkedAt ? formatDateTime(view.checkedAt) : "—"}</dd>
            </div>
            <div className="meta-row">
              <dt>앱 상태</dt>
              <dd>{appStatusLabel(view.appStatus)}</dd>
            </div>
          </dl>
          {view.reviewUrl && (
            <a
              className="button button-secondary w-full mt-5"
              href={view.reviewUrl}
              target="_blank"
              rel="noopener noreferrer"
            >
              <ExternalLink size={17} /> SecCheck에서 열기
            </a>
          )}
        </Card>
      </div>
    </div>
  );
}
  await expect(
    card.getByRole("link", { name: "Agent Hub 관리 설정 열기" }),
  ).toBeVisible();
  await expect(card.getByText("자세히")).toHaveCount(0);
});

test("보안 심의를 마쳐야 앱을 제출할 수 있다", async ({ page }) => {
  await installMockApi(page, { authenticated: true });
  await page.goto("/my/apps/ffffffff-ffff-4fff-8fff-ffffffffffff/security");
  await expect(page.getByRole("heading", { name: "보안 심의" })).toBeVisible();
  // The block an owner pastes into SecCheck, and no way past it yet.
  await expect(page.getByText("[APPSTORE-SECURITY-CHECK:v1]")).toBeVisible();
  await expect(page.getByRole("button", { name: /검토 제출/ })).toHaveCount(0);
  // The status list names the app's own state in Korean, not the stored enum.
  const appStatusRow = page.locator(".meta-row", { hasText: "앱 상태" });
  await expect(appStatusRow).toContainText("초안");
  await expect(appStatusRow).not.toContainText("draft");

  await page.getByLabel("심의 ID").fill("77777777-7777-4777-8777-777777777777");
  await page.getByRole("button", { name: /심의 결과 확인/ }).click();
  await expect(page.getByText(/보안 심의가 확인되었습니다/)).toBeVisible();
  await expect(page.getByRole("button", { name: /검토 제출/ })).toBeVisible();
});

test("관리자는 SecCheck 연동을 설정하고 연결을 확인한다", async ({ page }) => {
  await installMockApi(page, { authenticated: true });
  await page.goto("/admin/security-check");
  await expect(
    page.getByRole("heading", { name: "보안 심의 연동" }),
  ).toBeVisible();
  await expect(page.getByLabel("SecCheck 주소")).toHaveValue(
    "https://seccheck.internal.example",
  );
  // The stored key is never sent back to the screen.
  await expect(page.getByLabel("API Key")).toHaveValue("");
  await page.getByRole("button", { name: "연결 테스트" }).click();
  await expect(page.getByText(/SecCheck에 연결했습니다/)).toBeVisible();
});

test("검토자는 앱 내용과 이전 검토를 보고 의견과 함께 결정한다", async ({
  page,
}) => {
  await installMockApi(page, { authenticated: true });
  await page.goto("/review/dddddddd-dddd-4ddd-8ddd-dddddddddddd");
  // The app's name is both the page title and the heading of its card, so the
